function parseDurationMin(text) {
  const s = String(text).trim().toLowerCase();
  let minutes = null;
  let m;
  if (/^\d+$/.test(s)) {
    minutes = Number(s);
  } else if ((m = s.match(/^(\d+):(\d{2})$/))) {
    if (Number(m[2]) < 60) minutes = Number(m[1]) * 60 + Number(m[2]);
  } else if ((m = s.match(/^(?:(\d+)\s*h)?\s*(?:(\d+)\s*m)?$/)) && (m[1] || m[2])) {
    minutes = Number(m[1] ?? 0) * 60 + Number(m[2] ?? 0);
  }
  return minutes !== null && minutes > 0 ? minutes : null;
}

console.log(parseDurationMin('2h 15m'));
